"""Export document artifacts (Canvas / text documents) generated by Meta AI.

Meta AI's generated files are described by an ``html_artifact_sandbox`` block
inside the conversation payload. PDF artifacts use a ``/pdf`` viewer page;
DOCX and TXT artifacts use a ``/document`` page. The viewer's Next.js flight
payload contains the original DOCX bytes as base64 or the TXT content as text.
PDF pages similarly embed the original PDF bytes::

    https://<asset_id>.a.metaaiusercontent.com/pdf?artifact_uuid=...&ext=...&hash=...

That viewer page renders the document with pdf.js and embeds the PDF Meta
generated server-side (ReportLab) as a base64 string in ``pdfBase64``. Reading
that field gives the exact original PDF bytes, with selectable text, so no
local rendering step is required.

Typical use::

    exporter = DocumentExporter(cookies=cookies)
    documents = exporter.list_documents("CONVERSATION_ID")
    document = exporter.download("CONVERSATION_ID")
"""
from __future__ import annotations

import base64
import binascii
import io
import json
import re
import zipfile
from typing import Any, Dict, List, Optional
from urllib.parse import urlsplit

import requests

from .exceptions import DocumentExportError
from .utils import DEFAULT_UA

CONVERSATION_URL = "https://www.meta.ai/prompt/{conversation_id}"
PDF_HOST_SUFFIX = ".metaaiusercontent.com"
MAX_DOCUMENT_BYTES = 25 * 1024 * 1024
DOCUMENT_MIME_TYPES = {
    "pdf": "application/pdf",
    "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "txt": "text/plain",
}

# The conversation page embeds its data as JSON inside an RSC payload, so
# quotes arrive escaped (\" and \u0026).
_ESCAPED_QUOTE = re.compile(r'\\+"')
_PDF_BASE64 = re.compile(r'pdfBase64\\?"\s*:\s*\\?"([A-Za-z0-9+/=]+)')
# The current web build stores the payload in an RSC flight row and leaves a
# reference ("pdfBase64":"$17") in the model, so also accept the raw base64 of
# a PDF header ("%PDF" -> "JVBERi").
_RAW_PDF_BASE64 = re.compile(r"JVBERi[A-Za-z0-9+/=]{40,}")
_FLIGHT_PDF_ROW = re.compile(r"T([0-9a-fA-F]{1,8}),(JVBERi[A-Za-z0-9+/=]{40,})")
_FLIGHT_BINARY_ROW = re.compile(r"T([0-9a-fA-F]{1,8}),([A-Za-z0-9+/=]{40,})")
_FLIGHT_SCRIPT = re.compile(r'__next_f\.push\(\[1,("(?:\\.|[^"\\])*")\]\)')
_FLIGHT_ROW_START = re.compile(r"(?:^|\n)[0-9a-fA-F]{1,8}:")


def _decode_pdf_base64(encoded: str) -> Optional[bytes]:
    """Decode a base64 run that may carry a few trailing characters of the next
    token, since Meta's flight rows are not delimited from what follows."""
    stripped = encoded.rstrip("=")
    for drop in range(4):
        body = stripped[: len(stripped) - drop] if drop else stripped
        if len(body) < 40:
            break
        try:
            data = base64.b64decode(body + "=" * (-len(body) % 4), validate=True)
        except (binascii.Error, ValueError):
            continue
        if data.startswith(b"%PDF"):
            return data
    return None


def _extract_flight_binary(page: str) -> Optional[bytes]:
    """Decode a length-prefixed base64 binary row from a Next.js flight payload."""
    for match in _FLIGHT_BINARY_ROW.finditer(page):
        try:
            encoded_length = int(match.group(1), 16)
        except ValueError:
            continue
        if encoded_length < 40 or len(match.group(2)) < encoded_length:
            continue
        encoded = match.group(2)[:encoded_length]
        try:
            data = base64.b64decode(encoded, validate=True)
        except (binascii.Error, ValueError):
            continue
        if data:
            return data
    return None


def _extract_docx(page: str) -> Optional[bytes]:
    """Extract a DOCX zip payload embedded in the document viewer's flight row."""
    data = _extract_flight_binary(page)
    if not data or not data.startswith(b"PK\x03\x04") or len(data) > MAX_DOCUMENT_BYTES:
        return None
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            names = set(archive.namelist())
    except (OSError, zipfile.BadZipFile):
        return None
    if "[Content_Types].xml" not in names or "word/document.xml" not in names:
        return None
    return data


def _extract_text_document(page: str) -> Optional[bytes]:
    """Recover the exact UTF-8 text stored in Meta's TextViewer component props."""
    decoder = json.JSONDecoder()

    def find_content(value: Any) -> Optional[str]:
        if isinstance(value, dict):
            content = value.get("content")
            if isinstance(content, str):
                return content
            for child in value.values():
                found = find_content(child)
                if found is not None:
                    return found
        elif isinstance(value, list):
            for child in value:
                found = find_content(child)
                if found is not None:
                    return found
        return None

    for script_match in _FLIGHT_SCRIPT.finditer(page):
        try:
            flight = json.loads(script_match.group(1))
        except ValueError:
            continue
        if not isinstance(flight, str):
            continue
        viewer = flight.rfind('"TextViewer"')
        if viewer < 0:
            continue
        for row_match in _FLIGHT_ROW_START.finditer(flight[viewer:]):
            start = viewer + row_match.end()
            try:
                row, _ = decoder.raw_decode(flight, start)
            except ValueError:
                continue
            content = find_content(row)
            if content is None:
                continue
            try:
                data = content.encode("utf-8")
            except UnicodeEncodeError:
                continue
            return data if len(data) <= MAX_DOCUMENT_BYTES else None
    return None


def _unescape(payload: str) -> str:
    return (
        payload.replace('\\"', '"')
        .replace("\\u0026", "&")
        .replace("\\u003c", "<")
        .replace("\\u003e", ">")
        .replace("\\/", "/")
    )


def _balanced_object(text: str, start: int) -> Optional[str]:
    """Return the JSON object that begins at ``start`` (which points at '{')."""
    depth = 0
    in_string = False
    escaped = False
    for index in range(start, len(text)):
        char = text[index]
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return text[start : index + 1]
    return None


def is_allowed_document_url(url: str) -> bool:
    """Only accept HTTPS document URLs on Meta's signed asset host family."""
    try:
        parsed = urlsplit(url)
        hostname = (parsed.hostname or "").lower().rstrip(".")
    except ValueError:
        return False
    return (
        parsed.scheme == "https"
        and not parsed.username
        and not parsed.password
        and parsed.port in (None, 443)
        and hostname.endswith(PDF_HOST_SUFFIX)
    )


def parse_document_artifacts(html: str) -> List[Dict[str, Any]]:
    """Extract document artifacts from a conversation page's HTML payload."""
    text = _unescape(html)
    artifacts: List[Dict[str, Any]] = []
    seen = set()
    cursor = 0
    while True:
        marker = text.find('"html_artifact_sandbox":{', cursor)
        if marker < 0:
            break
        brace = text.find("{", marker)
        blob = _balanced_object(text, brace)
        cursor = brace + 1
        if not blob:
            continue
        try:
            sandbox = json.loads(blob)
        except ValueError:
            continue
        if not isinstance(sandbox, dict):
            continue
        uuid = str(sandbox.get("uuid") or "")
        url = str(sandbox.get("url") or "")
        if not uuid or uuid in seen or not is_allowed_document_url(url):
            continue
        seen.add(uuid)
        extension = str(sandbox.get("file_extension") or "").strip().lower()
        title = str(sandbox.get("title") or "Generated").strip()
        artifacts.append(
            {
                "artifact_uuid": uuid,
                "asset_id": str(sandbox.get("asset_id") or ""),
                "title": title,
                "file_extension": extension,
                "file_name": f"{title}.{extension}" if extension else title,
                "artifact_type": str(sandbox.get("artifact_type") or ""),
                "mime_type": DOCUMENT_MIME_TYPES.get(extension, ""),
                "viewer_actions": list(sandbox.get("viewer_actions") or []),
                "url": url,
            }
        )
    return artifacts


class DocumentExporter:
    """Resolve and download documents generated by Meta AI in a conversation."""

    def __init__(
        self,
        session: Optional[requests.Session] = None,
        cookies: Optional[Dict[str, str]] = None,
        access_token: Optional[str] = None,
        user_agent: str = DEFAULT_UA,
    ):
        self.cookies = cookies or {}
        self.access_token = access_token
        self.user_agent = user_agent
        self.session = session or requests.Session()
        if cookies and hasattr(self.session, "cookies"):
            self.session.cookies.update(cookies)

    def _headers(self) -> Dict[str, str]:
        headers = {
            "User-Agent": self.user_agent,
            "Accept": "text/html,application/xhtml+xml",
            "Referer": "https://www.meta.ai/",
        }
        if self.access_token:
            headers["Authorization"] = f"ecto1:{self.access_token}"
        return headers

    def list_documents(self, conversation_id: str) -> List[Dict[str, Any]]:
        """Return the downloadable documents attached to one conversation."""
        conversation_id = str(conversation_id or "").strip()
        if not conversation_id:
            raise DocumentExportError("A conversation ID is required")
        if not re.fullmatch(r"[A-Za-z0-9-]{8,64}", conversation_id):
            raise DocumentExportError("Conversation ID has an unexpected format")
        url = CONVERSATION_URL.format(conversation_id=conversation_id)
        try:
            response = self.session.get(url, headers=self._headers(), timeout=30)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise DocumentExportError(f"Could not read the conversation: {exc}") from exc
        documents = parse_document_artifacts(response.text)
        for index, document in enumerate(documents):
            document["index"] = index
        return documents

    def fetch_document_file(self, url: str, extension: str) -> bytes:
        """Fetch a signed viewer page and recover its original supported file bytes."""
        if not is_allowed_document_url(url):
            raise DocumentExportError("Meta returned an unsupported document host")
        extension = str(extension or "").lower().lstrip(".")
        if extension not in DOCUMENT_MIME_TYPES:
            raise DocumentExportError(f"Meta document format .{extension} has no file export")
        path = urlsplit(url).path
        expected_path = "/pdf" if extension == "pdf" else "/document"
        if path != expected_path:
            raise DocumentExportError("Meta returned an unexpected document viewer path")
        try:
            response = self.session.get(url, headers=self._headers(), timeout=60)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise DocumentExportError(f"Could not open the document page: {exc}") from exc
        extractors = {
            "pdf": self._extract_pdf,
            "docx": _extract_docx,
            "txt": _extract_text_document,
        }
        data = extractors[extension](response.text)
        if data is None:
            raise DocumentExportError(
                f"Meta's document page did not embed a .{extension} file; "
                "this artifact type has no file export"
            )
        return data

    def fetch_document_pdf(self, url: str) -> bytes:
        """Backward-compatible PDF-specific wrapper."""
        return self.fetch_document_file(url, "pdf")

    @staticmethod
    def _extract_pdf(page: str) -> Optional[bytes]:
        # Preferred: the flight row carries its own byte length, e.g.
        # 17:T50d4,JVBERi0xLjQK... so the payload can be cut exactly.
        for match in _FLIGHT_PDF_ROW.finditer(page):
            try:
                length = int(match.group(1), 16)
            except ValueError:
                continue
            payload = match.group(2)[:length]
            data = _decode_pdf_base64(payload)
            if data:
                return data
        # Fallbacks: a literal field or a bare base64 run.
        candidates = [m.group(1) for m in _PDF_BASE64.finditer(page)]
        candidates += [m.group(0) for m in _RAW_PDF_BASE64.finditer(page)]
        for encoded in candidates:
            data = _decode_pdf_base64(encoded)
            if data:
                return data
        return None

    def download(self, conversation_id: str, index: int = 0) -> Dict[str, Any]:
        """Download one document from a conversation by its zero-based index."""
        documents = self.list_documents(conversation_id)
        exportable = [
            d for d in documents
            if d.get("file_extension") in DOCUMENT_MIME_TYPES
        ]
        if not exportable:
            raise DocumentExportError(
                "This conversation has no downloadable supported Meta AI document"
            )
        if index < 0 or index >= len(exportable):
            raise DocumentExportError(
                f"Document index {index} is out of range; {len(exportable)} available"
            )
        document = exportable[index]
        extension = document["file_extension"]
        data = self.fetch_document_file(document["url"], extension)
        return {
            **document,
            "file_bytes": data,
            "file_size": len(data),
            "mime_type": DOCUMENT_MIME_TYPES[extension],
        }
